import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'mock-probe',
  description:
    'Probe the live fake calendar service for this eval: lists the upcoming events and fetches the full detail (attendees included) of the first one. Outputs the raw JSON responses as evidence for the brief.',
  inputs: {},
  outputs: {
    upcoming: { type: 'string', description: 'Raw JSON body from the upcoming-events listing.' },
    detail: { type: 'string', description: 'Raw JSON body of the first upcoming event, attendees included.' },
  },
  requires: ['workspace.read', 'network', 'credential:mock.calendar'],
});

const services = JSON.parse(await gezel.fs.read('mocks/services.json'));
const base = (id) => {
  const service = services.find((entry) => entry.id === id);
  if (!service) throw new Error(`mock service "${id}" is not listed in mocks/services.json`);
  return service.baseUrl;
};

const upcoming = await gezel.http.authed(`${base('calendar')}/api/events/upcoming`, {
  credential: 'mock.calendar',
});
if (!upcoming.ok) throw new Error(`upcoming listing failed: ${upcoming.status} ${upcoming.body}`);

const first = JSON.parse(upcoming.body).events[0];
const detail = await gezel.http.authed(`${base('calendar')}/api/events/${first.id}`, {
  credential: 'mock.calendar',
});
if (!detail.ok) throw new Error(`event detail failed: ${detail.status} ${detail.body}`);

gezel.output({ upcoming: upcoming.body, detail: detail.body });
